{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/story-tabs.json
    A story in steps (years or slides). Axes: layout (years: a row of year tabs over the panel of the active year with its badge, step, title, text and tag; carousel: the heading beside a picture with previous and next arrows and one dot per step), tone. Choosing a step emits `select`.
    Props (p): id, title, lead, badge, steps, active, labels, layout, tone, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_lead = (p.lead ?? '') -%}
{%- set v_badge = (p.badge ?? '') -%}
{%- set v_steps = (p.steps ?? null) -%}
{%- set v_active = (p.active ?? null) -%}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_layout = (p.layout ?? 'years') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- if ui_t(ui_eq(v_layout, 'years')) %}
  {%- set c_5 -%}
    {%- set c_4 -%}
      {%- for v_s in ui_l(v_steps) %}
        {%- set c_3 -%}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_s, ['date'])) }}
          {%- endset -%}
          {{ include('ui/inline/inline.html.twig', {'p': {'Class': 'text-sm font-semibold'}, 'children': c_1}, with_context = false) }}
          {%- set c_2 -%}
            {{ ui_text(ui_get(v_s, ['tag'])) }}
          {%- endset -%}
          {{ include('ui/inline/inline.html.twig', {'p': {'Class': 'text-xs'}, 'children': c_2}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/button/button.html.twig', {'p': {'Variant': ui_s((ui_t(ui_eq(ui_get(v_s, ['id']), v_active)) ? 'default' : 'outline')), 'Size': 'lg', 'Type': 'button', 'Class': 'h-auto flex-col items-start gap-0 py-2 text-start', 'Attrs': ui_attrs(['data-testid', 'story-tab', 'data-active', (ui_t(ui_eq(ui_get(v_s, ['id']), v_active)) ? 'true' : 'false')])}, 'children': c_3}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/box/box.html.twig', {'p': {'Class': 'grid grid-cols-2 gap-2 sm:grid-cols-4', 'Attrs': ui_attrs(['data-testid', 'story-tabs'])}, 'children': c_4}, with_context = false) }}
    {%- for v_s in ui_l(v_steps) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_eq(ui_get(v_s, ['id']), v_active)) %}
        {{ include('blocks/story-panel.html.twig', {'p': {'s': v_s, 'index': v_i, 'total': ui_len(v_steps), 'labels': v_labels}}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'lead': v_lead, 'heading': {'badge': v_badge}, 'tone': v_tone, 'landmarkLabel': v_landmarkLabel}, 'children': c_5}, with_context = false) }}
{%- else %}
  {%- set f_6 -%}
    {%- set c_10 -%}
      {{ include('blocks/media-frame.html.twig', {'p': {'alt': v_title, 'ratio': '4/3'}}, with_context = false) }}
      {%- set c_9 -%}
        {%- set c_7 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'chevron-left', 'Size': 16}}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'sm', 'Layout': 'icon', 'Type': 'button', 'AriaLabel': ui_s(ui_get(v_labels, ['previous'])), 'Attrs': ui_attrs(['data-testid', 'story-arrow'])}, 'children': c_7}, with_context = false) }}
        {{ include('blocks/story-dots.html.twig', {'p': {'steps': v_steps, 'active': v_active}}, with_context = false) }}
        {%- set c_8 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'chevron-right', 'Size': 16}}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'sm', 'Layout': 'icon', 'Type': 'button', 'AriaLabel': ui_s(ui_get(v_labels, ['next'])), 'Attrs': ui_attrs(['data-testid', 'story-arrow'])}, 'children': c_8}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center', 'Justify': 'between'}, 'children': c_9}, with_context = false) }}
    {%- endset -%}
    {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '4', 'Align': 'stretch'}, 'children': c_10}, with_context = false) }}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'lead': v_lead, 'heading': {'badge': v_badge}, 'tone': v_tone, 'layout': 'split', 'media': {'show': true}, 'landmarkLabel': v_landmarkLabel, 'aside': f_6}}, with_context = false) }}
{%- endif %}
